class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            counts = [0] * 26
            distinct = 0
            mx = 0
            # substring s[j:i], j goes from i-1 down to 0
            for j in range(i - 1, -1, -1):
                c = ord(s[j]) - ord('a')
                if counts[c] == 0:
                    distinct += 1
                counts[c] += 1
                if counts[c] > mx:
                    mx = counts[c]
                length = i - j
                if distinct * mx == length:
                    if dp[j] + 1 < dp[i]:
                        dp[i] = dp[j] + 1
        return dp[n]
