    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            # consider substrings s[j:i] ending at i-1
            freq = {}
            cnt_of_freq = {}
            distinct_freqs = 0  # number of frequency values with nonzero count
            for j in range(i - 1, -1, -1):
                c = s[j]
                old = freq.get(c, 0)
                if old > 0:
                    cnt_of_freq[old] -= 1
                    if cnt_of_freq[old] == 0:
                        distinct_freqs -= 1
                new = old + 1
                freq[c] = new
                cnt_of_freq[new] = cnt_of_freq.get(new, 0) + 1
                if cnt_of_freq[new] == 1:
                    distinct_freqs += 1
                if distinct_freqs == 1 and dp[j] + 1 < dp[i]:
                    dp[i] = dp[j] + 1
        return dp[n]
