    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        # balanced[j][i] computed on the fly
        for j in range(n):
            if dp[j] == INF:
                continue
            cnt = [0] * 26
            freq = {}  # count value -> number of characters with that count
            for i in range(j, n):
                c = ord(s[i]) - 97
                x = cnt[c]
                if x > 0:
                    freq[x] -= 1
                    if freq[x] == 0:
                        del freq[x]
                cnt[c] = x + 1
                freq[x + 1] = freq.get(x + 1, 0) + 1
                if len(freq) == 1:
                    if dp[j] + 1 < dp[i + 1]:
                        dp[i + 1] = dp[j] + 1
        return dp[n]
class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)
        # prefix counts
        letters = sorted(set(s))
        idx = {c: k for k, c in enumerate(letters)}
        m = len(letters)
        pref = [[0] * m]
        for ch in s:
            row = pref[-1][:]
            row[idx[ch]] += 1
            pref.append(row)

        def balanced(j, i):
            a = pref[i]
            b = pref[j]
            target = -1
            for k in range(m):
                d = a[k] - b[k]
                if d:
                    if target == -1:
                        target = d
                    elif d != target:
                        return False
            return target != -1

        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            best = INF
            for j in range(i):
                if dp[j] + 1 < best and balanced(j, i):
                    best = dp[j] + 1
            dp[i] = best
        return dp[n]

