def validate(inp):
    try:
        lines = inp.strip("\n").split("\n")
        if len(lines) != 1:
            return False
        s = json.loads(lines[0])
        if not isinstance(s, str):
            return False
        return 1 <= len(s) <= 1000 and all("a" <= ch <= "z" for ch in s)
    except Exception:
        return False

def _balanced(t):
    c = Counter(t)
    return len(set(c.values())) <= 1

def ref(inp):
    s = json.loads(inp.strip("\n"))
    n = len(s)
    best = n
    # Try every set of cut positions (cut after index i, for i in 0..n-2).
    for mask in range(1 << (n - 1)):
        parts = []
        start = 0
        for i in range(n - 1):
            if (mask >> i) & 1:
                parts.append(s[start:i + 1])
                start = i + 1
        parts.append(s[start:])
        if all(_balanced(p) for p in parts):
            best = min(best, len(parts))
    return json.dumps(best)
